/**
 * Format currency number helper
 */
function formatNum(val?: number): string {
  if (val === undefined || val === null) return '0';
  return new Intl.NumberFormat('en-US').format(val);
}

function formatMoneyIdr(val?: number): string {
  if (val === undefined || val === null) return 'IDR 0';
  return `IDR ${new Intl.NumberFormat('en-US').format(val)}`;
}

/**
 * Number to words converter for Indonesian (Terbilang)
 */
function angkaKeKata(n: number): string {
  const satuan = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];
  if (n < 12) return satuan[n];
  if (n < 20) return angkaKeKata(n - 10) + ' belas';
  if (n < 100) return angkaKeKata(Math.floor(n / 10)) + ' puluh ' + (n % 10 !== 0 ? satuan[n % 10] : '');
  if (n < 200) return 'seratus ' + (n - 100 !== 0 ? angkaKeKata(n - 100) : '');
  if (n < 1000) return satuan[Math.floor(n / 100)] + ' ratus ' + (n % 100 !== 0 ? angkaKeKata(n % 100) : '');
  if (n < 2000) return 'seribu ' + (n - 1000 !== 0 ? angkaKeKata(n - 1000) : '');
  if (n < 1000000) return angkaKeKata(Math.floor(n / 1000)) + ' ribu ' + (n % 1000 !== 0 ? angkaKeKata(n % 1000) : '');
  if (n < 1000000000) return angkaKeKata(Math.floor(n / 1000000)) + ' juta ' + (n % 1000000 !== 0 ? angkaKeKata(n % 1000000) : '');
  if (n < 1000000000000) return angkaKeKata(Math.floor(n / 1000000000)) + ' miliar ' + (n % 1000000000 !== 0 ? angkaKeKata(n % 1000000000) : '');
  return angkaKeKata(Math.floor(n / 1000000000000)) + ' triliun ' + (n % 1000000000000 !== 0 ? angkaKeKata(n % 1000000000000) : '');
}

/**
 * Number to words converter for English
 */
function numberToEnglishWords(n: number): string {
  const ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
    'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
    'seventeen', 'eighteen', 'nineteen'];
  const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

  if (n === 0) return 'zero';

  function convertChunk(num: number): string {
    let str = '';
    if (num >= 100) {
      str += ones[Math.floor(num / 100)] + ' hundred ';
      num %= 100;
    }
    if (num >= 20) {
      str += tens[Math.floor(num / 10)] + (num % 10 !== 0 ? '-' + ones[num % 10] : '') + ' ';
    } else if (num > 0) {
      str += ones[num] + ' ';
    }
    return str.trim();
  }

  let result = '';
  if (n >= 1000000000000) {
    result += convertChunk(Math.floor(n / 1000000000000)) + ' trillion ';
    n %= 1000000000000;
  }
  if (n >= 1000000000) {
    result += convertChunk(Math.floor(n / 1000000000)) + ' billion ';
    n %= 1000000000;
  }
  if (n >= 1000000) {
    result += convertChunk(Math.floor(n / 1000000)) + ' million ';
    n %= 1000000;
  }
  if (n >= 1000) {
    result += convertChunk(Math.floor(n / 1000)) + ' thousand ';
    n %= 1000;
  }
  if (n > 0) {
    result += convertChunk(n);
  }
  return result.trim();
}

/**
 * Generate Format 2: Official BUMN / Corporate Standard Commercial Invoice (1 Page)
 */
export function generateFormat2InvoicePDF(params?: Format2InvoiceParams) {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const pageWidth = doc.internal.pageSize.width; // 210mm
  const pageHeight = doc.internal.pageSize.height; // 297mm

  // Default values: PT Coreterra as Issuer/Publisher, Client as Customer
  const custName = params?.customerName || 'PT Solusi Monitoring Indonesia';
  const custAddr = params?.customerAddress || 'Gedung Menara Mulia Lt. 12, Jl. Gatot Subroto Kav. 9-11, Karet Semanggi, Setiabudi, Jakarta Selatan 12930';
  const custNpwp = params?.customerNpwp || '01.234.567.8-012.000';
  const custCode = params?.customerCode || 'SMI-2026';
  
  const invNumber = params?.invoiceNumber || 'INV/001/004_IKPT-SOLOK-001/08/2026';
  const invDate = params?.invoiceDate || '18 August 2026';
  
  const compName = params?.companyName || 'PT CORETERRA GEO ENGINEERING';
  const compNpwp = params?.companyNpwp || '1000 0000 1002 1192';
  const compHeadOffice = params?.companyAddress || 'Gardenia Estate, Blok A5 No 12 RT 007 RW 014, Ciputat, Kota Tangerang Selatan, Banten 15411';
  const compBranch = params?.companyBranch || 'Head Office Tangerang Selatan & Jakarta';
  
  const orderNo = params?.orderNumber || 'ORD-004-IKPT-001';
  const contractNo = params?.contractNumber || 'KONTRAK/004_IKPT-SOLOK-001/2026';
  const poNo = params?.poNumber || 'PO-IKPT-SOLOK-2026-08';
  const activityTitle = params?.activityTitle || 'Washbore Borpile & Foundation Project, Muara Laboh, West Sumatera';
  const activityPeriod = params?.activityPeriod || '01 August 2026 - 31 August 2026';
  
  const fee = params?.feeAmount ?? 19000000;
  const otherExp = params?.otherExpenses ?? 0;
  const advPayment = params?.advancePayment ?? 0;
  const totalSub = fee + otherExp - advPayment;
  const discount = params?.discountAmount ?? 0;
  const dpp = totalSub - discount;
  const dppLain = params?.dppLainnya ?? (dpp > 0 ? Math.round(dpp * 11 / 12) : 0);
  const taxPct = params?.taxPercentage ?? 12.0;
  const tax = params?.taxAmount ?? (dppLain > 0 ? Math.round(dppLain * (taxPct / 100)) : (dpp > 0 ? Math.round(dpp * 0.11) : 0));
  const totalAfterVat = dpp + tax;
  const reimburse = params?.reimburseAmount ?? 0;
  const deposit = params?.depositAmount ?? 0;
  const grandTotal = params?.totalAmount ?? (totalAfterVat + reimburse - deposit);
  
  const totalContract = params?.totalContractAmount || 42180000;
  const signatory = params?.signatoryName || 'Setyo Mardani';
  
  let defaultSettings: any = {};
  try {
    const settingsStr = localStorage.getItem('ansa-settings-storage');
    if (settingsStr) {
      const parsed = JSON.parse(settingsStr);
      if (parsed?.state?.settings) {
        defaultSettings = parsed.state.settings;
      }
    }
  } catch (e) {}

  const bankName = params?.bankName || defaultSettings.bankName || 'Bank Mandiri KCP Jakarta Gedung Jaya';
  const bankAcc = params?.bankAccountNo || defaultSettings.bankAccountNumber || '103-00-1332575-4';
  const bankAccName = params?.bankAccountName || defaultSettings.bankAccountName || defaultSettings.companyName || 'PT Coreterra Geo Engineering';
  const mvaIdr = params?.mvaIdr || '88101 278162';
  const mvaUsd = params?.mvaUsd || '88202 278162';

  // 1. TOP HEADER TITLE & LOGO
  let y = 10;

  // Title Center: INVOICE / KUITANSI
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(30, 41, 59); // Slate 800
  doc.text('INVOICE', 105, y + 4, { align: 'center' });
  doc.text('KUITANSI', 105, y + 8, { align: 'center' });

  // Right Logo: PT Coreterra Geo Engineering Logo
  try {
    doc.addImage(LOGO_CORETERRA_BASE64, 'PNG', 166, y - 2, 34, 13);
  } catch (e) {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(14, 116, 144);
    doc.text('CORETERRA', 198, y + 6, { align: 'right' });
  }

  y = 24;

  // 2. SUBHEADER: CLIENT INFO (LEFT) & METADATA (RIGHT)
  // Left Side: Client Info
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(15, 23, 42);
  doc.text(custName.toUpperCase(), 12, y);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(71, 85, 105);
  
  const splitCustAddr = doc.splitTextToSize(custAddr, 72);
  doc.text(splitCustAddr, 12, y + 3.5);
  
  const addrLines = splitCustAddr.length;
  const npwpY = y + 3.5 + (addrLines * 2.8);
  doc.text(`NPWP/ Tax ID Number   :  ${custNpwp}`, 12, npwpY);

  // Right Side: Invoice Meta & Publisher Info
  const rightX = 92;
  const rightValX = 135;

  doc.setFontSize(6.8);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(51, 65, 85);

  doc.text('Kode Pelanggan / Account Number', rightX, y);
  doc.text(`:   ${custCode}`, rightValX, y);

  doc.text('No. Invoice / Invoice Number', rightX, y + 3.5);
  doc.setFont('helvetica', 'bold');
  doc.text(`:   ${invNumber}`, rightValX, y + 3.5);

  doc.setFont('helvetica', 'normal');
  doc.text('Tgl. Invoice / Invoice Date', rightX, y + 7.0);
  doc.text(`:   ${invDate}`, rightValX, y + 7.0);

  // Publisher Info
  const pubY = y + 11.5;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.0);
  doc.setTextColor(15, 23, 42);
  doc.text(compName, rightX, pubY);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(71, 85, 105);
  doc.text('NPWP/ Tax ID Number', rightX, pubY + 3.5);
  doc.text(`:   ${compNpwp}`, rightValX, pubY + 3.5);

  doc.text('Kantor Pusat / Head Office', rightX, pubY + 7.0);
  const splitHead = doc.splitTextToSize(compHeadOffice, 60);
  doc.text(`:`, rightValX, pubY + 7.0);
  doc.text(splitHead, rightValX + 2, pubY + 7.0);

  const headLines = splitHead.length;
  const branchY = pubY + 7.0 + (headLines * 2.6);
  doc.text('Kantor Penerbit / Published By', rightX, branchY);
  doc.text(`:   ${compBranch}`, rightValX, branchY);

  // 3. SEPARATOR HEADER LINE
  y = 51;
  doc.setDrawColor(203, 213, 225); // Slate 300
  doc.setLineWidth(0.3);
  doc.line(12, y, 198, y);

  // 4. ORDER / CONTRACT DETAILS BAR
  y += 4;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.2);
  doc.setTextColor(30, 41, 59);
  doc.text('Keterangan / Description', 55, y);
  doc.text('Jumlah / Amount', 175, y, { align: 'right' });

  y += 1.5;
  doc.setDrawColor(226, 232, 240);
  doc.line(12, y, 198, y);

  // Order Details Sub-table
  y += 3.5;
  const orderDetails = [
    ['No. / Tgl. Order', `:  ${orderNo}`],
    ['No.OC / No. Kontrak/ Tanggal', `:  ${contractNo}`],
    ['No.Reff: PO/ WO/ SPK/ Tanggal', `:  ${poNo}`],
    ['Kegiatan / Intervention *)', `:  ${activityTitle}`],
    ['Tgl. Pelaksanaan/ Date of Intervention', `:  ${activityPeriod}`],
  ];

  orderDetails.forEach(([lbl, val]) => {
    doc.setFontSize(6.8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text(lbl, 14, y);
    doc.setFont('helvetica', lbl.includes('Kegiatan') ? 'bold' : 'normal');
    doc.setTextColor(15, 23, 42);
    doc.text(val, 80, y);
    y += 3.4;
  });

  y += 1.5;
  doc.setDrawColor(226, 232, 240);
  doc.line(12, y, 198, y);

  // 5. FINANCIAL BREAKDOWN ROWS
  y += 3.5;
  const finRows = [
    { label: 'Fee Kegiatan / Fee', val: fee, bold: false },
    { label: 'Biaya Lain / Other Expenses', val: otherExp, bold: false },
    { label: 'Uang Muka / Advance Payment', val: advPayment, bold: false },
    { label: 'Total', val: totalSub, bold: true, lineAbove: true },
    { label: 'Diskon/ Discount', val: discount, bold: false },
    { label: 'Dasar Pengenaan Pajak (DPP) / Net Amount', val: dpp, bold: false, lineAbove: true },
    { label: 'Dasar Pengenaan Pajak (DPP) Lainnya', val: dppLain, bold: false },
    { label: `PPN / VAT (${taxPct.toFixed(2)}% x DPP Lainnya)`, val: tax, bold: false },
    { label: 'Total Setelah Pajak / Total After VAT', val: totalAfterVat, bold: true, lineAbove: true },
    { label: 'Reimburse', val: reimburse, bold: false },
    { label: 'Deposit / Jaminan Pekerjaan', val: deposit, bold: false },
    { label: 'Grand Total', val: grandTotal, bold: true, lineAbove: true, doubleLineBelow: true },
  ];

  finRows.forEach((r) => {
    if (r.lineAbove) {
      doc.setDrawColor(241, 245, 249);
      doc.line(78, y - 1.2, 198, y - 1.2);
    }

    doc.setFontSize(6.8);
    doc.setFont('helvetica', r.bold ? 'bold' : 'normal');
    doc.setTextColor(15, 23, 42);
    doc.text(r.label, 80, y);

    // Currency & Value
    doc.setFont('helvetica', 'normal');
    doc.text('IDR', 165, y);
    doc.setFont('helvetica', r.bold ? 'bold' : 'normal');
    doc.text(formatNum(r.val), 198, y, { align: 'right' });

    if (r.doubleLineBelow) {
      doc.setDrawColor(203, 213, 225);
      doc.line(78, y + 1.2, 198, y + 1.2);
      doc.line(78, y + 1.6, 198, y + 1.6);
    }

    y += 3.4;
  });

  // 6. TERBILANG & INFORMASI STRUKTUR DP & KONTRAK BOX
  y += 4;
  
  // Terbilang (Bilingual ID & EN)
  const wordsId = `${angkaKeKata(grandTotal)} rupiah`.trim();
  const wordsEn = `${numberToEnglishWords(grandTotal)} rupiah`.trim();
  const fullTerbilang = `${wordsId.charAt(0).toUpperCase() + wordsId.slice(1)} / ${wordsEn}`;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.0);
  doc.setTextColor(15, 23, 42);
  doc.text('Terbilang :', 12, y);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(6.5);
  doc.setTextColor(51, 65, 85);
  const splitTerbilang = doc.splitTextToSize(fullTerbilang, 116);
  doc.text(splitTerbilang, 12, y + 3.4);

  // Contract Structure Note Box (Exact Image 2 Style)
  const terbilangLines = splitTerbilang.length;
  const noteBoxY = y + 3.4 + (terbilangLines * 2.6) + 1.5;
  const noteBoxWidth = 116;
  const noteBoxHeight = 28;

  doc.setFillColor(248, 250, 252); // Slate 50 #F8FAFC
  doc.roundedRect(12, noteBoxY, noteBoxWidth, noteBoxHeight, 2, 2, 'F');
  doc.setDrawColor(203, 213, 225); // Slate 300 #CBD5E1
  doc.roundedRect(12, noteBoxY, noteBoxWidth, noteBoxHeight, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.2);
  doc.setTextColor(15, 23, 42); // Slate 900
  doc.text('INFORMASI STRUKTUR KONTRAK & PEMBAYARAN', 15, noteBoxY + 4.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(51, 65, 85); // Slate 700

  const dpAlloc = params?.totalDp ?? (params?.totalContractAmount || totalContract);
  const dpPaidPrev = params?.prevBilledDp ?? (params?.prevBilledTotal ?? 0);
  const currentInv = grandTotal;
  const remainingDp = Math.max(0, dpAlloc - dpPaidPrev - currentInv);
  const remainingContract = Math.max(0, totalContract - dpPaidPrev - currentInv);

  doc.text(`• Nilai Total Kontrak: Rp ${formatNum(totalContract)},-`, 15, noteBoxY + 8.5);
  doc.text(`• Total Dibayar Sebelumnya: Rp ${formatNum(dpPaidPrev)},- (Lunas)`, 15, noteBoxY + 12.5);
  doc.text(`• Tagihan Ini: Rp ${formatNum(currentInv)},-`, 15, noteBoxY + 16.5);
  doc.text(`• Sisa Kontrak Akhir: ${remainingContract > 0 ? `Rp ${formatNum(remainingContract)},-` : 'Rp 0,- (Lunas)'}`, 15, noteBoxY + 20.5);
  if (params?.prevInvoiceNum) {
    doc.text(`• Reff Invoice Lunas: ${params.prevInvoiceNum}`, 15, noteBoxY + 24.5);
  }

  // Legalities: e-Meterai & QR Code & Signature
  try {
    doc.addImage(METERAI_10000_BASE64, 'PNG', 132, y + 2, 20, 20);
  } catch (e) {
    doc.rect(132, y + 2, 20, 20);
  }

  try {
    doc.addImage(QR_VALIDATION_BASE64, 'PNG', 158, y + 1, 23, 23);
  } catch (e) {
    doc.rect(158, y + 1, 23, 23);
  }

  // Signatory Name & Title
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(15, 23, 42);
  doc.text(signatory.toUpperCase(), 170, y + 27, { align: 'center' });
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(71, 85, 105);
  doc.text('Director / Direktur', 170, y + 30.5, { align: 'center' });

  // 7. CATATAN / NOTES SECTION (BOTTOM BOX)
  y = 212;
  doc.setDrawColor(203, 213, 225);
  doc.setLineWidth(0.3);
  doc.line(12, y, 198, y);

  y += 4;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.2);
  doc.setTextColor(15, 23, 42);
  doc.text('CATATAN / NOTES', 12, y);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.2);
  doc.setTextColor(71, 85, 105);
  
  y += 3.2;
  doc.text('Pembayaran melalui transfer bank. Cantumkan nomor invoice pada slip transfer. Pembayaran ke nomor rekening : / Payment by bank transfer. Please ensure the invoice number', 12, y);
  y += 2.6;
  doc.text('stated clearly in your transfer slip. Payment account number :', 12, y);

  const notesList = [
    `a.  ${bankName} (IDR) A/C No. ${bankAcc} a.n. ${bankAccName}`,
    `b.  Mandiri Virtual Account atau MVA (Bank Mandiri dan Bank lainnya) / Mandiri Virtual Account or MVA (Bank Mandiri and others)`,
    `     • A/C IDR ${mvaIdr}    ||    A/C USD ${mvaUsd}`,
    `c.  Pembayaran melalui rekening lainnya harus sesuai kesepakatan kontrak atau perjanjian / Payment by other specified account should be written on contract or agreement`,
    `d.  Bukti pembayaran invoice segera dikirimkan kepada kami melalui email finance@coreterra.co.id / Kindly send scanned transfer slip to e-mail finance@coreterra.co.id`,
    `e.  Tagihan dalam USD yang dibayarkan menggunakan IDR agar menggunakan kurs pada tanggal pembayaran (kurs tengah BI) / In case your bill is USD and will be paid in IDR, kindly settle using USD exchange middle rate at Bank Indonesia on the date of transaction`,
    `f.   PT Coreterra Geo Engineering menggunakan meterai elektronik resmi sesuai ketentuan perpajakan yang berlaku`,
    `g.  Pejabat yang menandatangani dokumen ini merupakan pejabat yang ditunjuk dan berwenang, verifikasi dokumen dapat dilakukan dengan melakukan pindaian (scan) pada QRCode terlampir.`
  ];

  y += 3.2;
  notesList.forEach((line) => {
    const splitLine = doc.splitTextToSize(line, 184);
    doc.text(splitLine, 18, y);
    y += (splitLine.length * 2.5) + 0.8;
  });

  // Open PDF in new tab
  const blob = doc.output('blob');
  const url = URL.createObjectURL(blob);
  window.open(url, '_blank');
}
